import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

XLSX = "sales_data.xlsx"
MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
ET.register_namespace("", MAIN)


def col_to_num(letters):
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - 64)
    return n


def num_to_col(n):
    s = ""
    while n > 0:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s


def cell_ref(r):
    m = re.match(r"([A-Za-z]+)(\d+)", r or "")
    return (m.group(1), int(m.group(2))) if m else (None, None)


def parse_cell_value(c, shared):
    t = c.get("t")
    if t == "s":
        v = c.find(f"{{{MAIN}}}v")
        if v is not None and v.text is not None:
            idx = int(v.text)
            return shared[idx] if idx < len(shared) else None
        return None
    if t == "inlineStr":
        is_el = c.find(f"{{{MAIN}}}is")
        if is_el is not None:
            return "".join(x.text or "" for x in is_el.findall(f"{{{MAIN}}}t"))
        return None
    v = c.find(f"{{{MAIN}}}v")
    return v.text if v is not None else None


def is_blank(val):
    return val is None or (isinstance(val, str) and val.strip() == "")


def insert_sorted(row_el, new_c, col_num):
    children = list(row_el)
    pos = 0
    for i, ch in enumerate(children):
        col, _ = cell_ref(ch.get("r"))
        if col is not None and col_to_num(col) > col_num:
            pos = i
            break
        pos = i + 1
    row_el.insert(pos, new_c)


with zipfile.ZipFile(XLSX) as z:
    names = z.namelist()
    data = {n: z.read(n) for n in names}

sheet_path = None
for n in names:
    if re.match(r"xl/worksheets/sheet\d+\.xml$", n):
        sheet_path = n
        break
if sheet_path is None:
    print(json.dumps({"error": "no worksheet found"}))
    sys.exit(2)

shared = []
if "xl/sharedStrings.xml" in data:
    sroot = ET.fromstring(data["xl/sharedStrings.xml"])
    for si in sroot.findall(f"{{{MAIN}}}si"):
        shared.append("".join(x.text or "" for x in si.findall(f".//{{{MAIN}}}t")))

root = ET.fromstring(data[sheet_path])
sheetData = root.find(f"{{{MAIN}}}sheetData")
rows = sheetData.findall(f"{{{MAIN}}}row")

headers = {}
header_row_el = None
for row in rows:
    if row.get("r") == "1":
        header_row_el = row
        for c in row.findall(f"{{{MAIN}}}c"):
            col, _ = cell_ref(c.get("r"))
            if col:
                headers[col] = parse_cell_value(c, shared)
        break

sales_col = profit_col = cost_col = margin_col = None
for col, h in headers.items():
    hl = (h or "").strip().lower()
    if "margin" in hl:
        margin_col = col
    elif "profit" in hl or "income" in hl or "earnings" in hl:
        profit_col = col
    elif "cost" in hl or "expense" in hl or "cogs" in hl:
        cost_col = col
    elif "sales" in hl or "revenue" in hl:
        sales_col = col

max_col = 0
for row in rows:
    for c in row.findall(f"{{{MAIN}}}c"):
        col, _ = cell_ref(c.get("r"))
        if col:
            max_col = max(max_col, col_to_num(col))

if sales_col is None:
    print(json.dumps({"error": "no sales/revenue column found", "headers": headers}))
    sys.exit(2)
if profit_col is None and cost_col is None:
    print(json.dumps({"error": "no profit or cost column found", "headers": headers}))
    sys.exit(2)

if margin_col is None:
    new_col_num = max_col + 1
    mode = "added"
else:
    new_col_num = col_to_num(margin_col)
    mode = "updated-existing"

new_col_letter = num_to_col(new_col_num)

style_idx = None
if "xl/styles.xml" in data:
    try:
        styleroot = ET.fromstring(data["xl/styles.xml"])
        cellXfs = styleroot.find(f"{{{MAIN}}}cellXfs")
        if cellXfs is not None:
            xfs = cellXfs.findall(f"{{{MAIN}}}xf")
            if xfs:
                src = dict(xfs[0].attrib)
                src.pop("numFmtId", None)
                src.pop("applyNumberFormat", None)
                new_xf = ET.SubElement(cellXfs, "xf")
                new_xf.attrib.update(src)
                new_xf.set("numFmtId", "10")
                new_xf.set("applyNumberFormat", "1")
                style_idx = len(xfs)
    except Exception as e:
        style_idx = None

written = 0
skipped = []
for row in rows:
    r = row.get("r")
    if not r or r == "1":
        continue
    cells = {}
    for c in row.findall(f"{{{MAIN}}}c"):
        col, _ = cell_ref(c.get("r"))
        if col:
            cells[col_to_num(col)] = c
    sales_cell = cells.get(col_to_num(sales_col))
    num_col = profit_col if profit_col else cost_col
    num_cell = cells.get(col_to_num(num_col))
    if sales_cell is None or num_cell is None:
        skipped.append(int(r))
        continue
    sales_val = parse_cell_value(sales_cell, shared)
    num_val = parse_cell_value(num_cell, shared)
    if is_blank(sales_val) or is_blank(num_val):
        skipped.append(int(r))
        continue
    if profit_col:
        formula = f"{profit_col}{r}/{sales_col}{r}"
    else:
        formula = f"({sales_col}{r}-{cost_col}{r})/{sales_col}{r}"
    nc = ET.Element("c", {"r": f"{new_col_letter}{r}"})
    if style_idx is not None:
        nc.set("s", str(style_idx))
    f = ET.SubElement(nc, "f")
    f.text = formula
    insert_sorted(row, nc, new_col_num)
    written += 1

if mode == "added":
    hc = ET.Element("c", {"r": f"{new_col_letter}1", "t": "inlineStr"})
    is_el = ET.SubElement(hc, "is")
    t = ET.SubElement(is_el, "t")
    t.text = "Profit Margin (%)"
    insert_sorted(header_row_el, hc, new_col_num)

dim = root.find(f"{{{MAIN}}}dimension")
if dim is not None:
    ref = dim.get("ref") or ""
    if ":" in ref:
        start, end = ref.split(":")
        scol, srow = cell_ref(start)
        ecol, erow = cell_ref(end)
        if ecol and col_to_num(ecol) < new_col_num:
            dim.set("ref", f"{start}:{num_to_col(new_col_num)}{erow}")

def serialize(el):
    body = ET.tostring(el, encoding="unicode")
    return ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' + body).encode("utf-8")

tmp = XLSX + ".tmp"
with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
    for n in names:
        if n == sheet_path:
            zout.writestr(n, serialize(root))
        elif n == "xl/styles.xml" and style_idx is not None:
            zout.writestr(n, serialize(styleroot))
        else:
            zout.writestr(n, data[n])
os.replace(tmp, XLSX)

print(json.dumps({
    "mode": mode,
    "headers": headers,
    "sales_column": sales_col,
    "numerator_column": profit_col if profit_col else cost_col,
    "margin_column": new_col_letter,
    "formula_rows_written": written,
    "skipped_rows": skipped[:50],
    "sample_formula": f"={profit_col or ('(' + sales_col + '-' + cost_col + ')')}2/{sales_col}2" if False else None,
}))

