  1. Ensure LibreOffice Basic macro RecalculateAndSave exists.
  2. Run soffice headless with that macro on the workbook.
  3. Scan every cell for Excel error strings and count formulas.
"""
import json
import os
import platform
import subprocess
import sys
from pathlib import Path

from openpyxl import load_workbook

XLSX = "sales_data.xlsx"
ERRORS = ["#VALUE!", "#DIV/0!", "#REF!", "#NAME?", "#NULL!", "#NUM!", "#N/A"]


def macro_dir():
    if platform.system() == "Darwin":
        return Path.home() / "Library/Application Support/LibreOffice/4/user/basic/Standard"
    return Path.home() / ".config/libreoffice/4/user/basic/Standard"


def ensure_macro():
    d = macro_dir()
    f = d / "Module1.xba"
    if f.exists() and "RecalculateAndSave" in f.read_text():
        return True
    if not d.exists():
        subprocess.run(["soffice", "--headless", "--terminate_after_init"],
                       capture_output=True, timeout=10)
        d.mkdir(parents=True, exist_ok=True)
    basic = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<!DOCTYPE script:module PUBLIC "-//OpenOffice.org//DTD OfficeDocument 1.0//EN" "module.dtd">\n'
        '<script:module xmlns:script="http://openoffice.org/2000/script" '
        'script:name="Module1" script:language="StarBasic">\n'
        "    Sub RecalculateAndSave()\n"
        "      ThisComponent.calculateAll()\n"
        "      ThisComponent.store()\n"
        "      ThisComponent.close(True)\n"
        "    End Sub\n"
        "</script:module>\n"
    )
    try:
        f.write_text(basic)
        return True
    except OSError:
        return False


def run_recalc(path, timeout=30):
    if not Path(path).exists():
        return {"error": f"file missing: {path}"}
    if not ensure_macro():
        return {"error": "could not set up LibreOffice macro"}

    cmd = [
        "soffice", "--headless", "--norestore",
        "vnd.sun.star.script:Standard.Module1.RecalculateAndSave?language=Basic&location=application",
        str(Path(path).absolute()),
    ]
    if platform.system() == "Linux":
        cmd = ["timeout", str(timeout)] + cmd

    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode not in (0, 124):
        return {"error": proc.stderr or f"soffice exited {proc.returncode}"}

    return scan(path)


def scan(path):
    wb = load_workbook(path, data_only=True)
    found = {e: [] for e in ERRORS}
    total = 0
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for cell in row:
                if isinstance(cell.value, str):
                    for e in ERRORS:
                        if e in cell.value:
                            found[e].append(f"{ws.title}!{cell.coordinate}")
                            total += 1
                            break
    wb.close()

    wbf = load_workbook(path, data_only=False)
    formulas = sum(
        1
        for ws in wbf.worksheets
        for row in ws.iter_rows()
        for cell in row
        if isinstance(cell.value, str) and cell.value.startswith("=")
    )
    wbf.close()

    summary = {e: {"count": len(v), "locations": v[:20]} for e, v in found.items() if v}
    return {
        "status": "success" if total == 0 else "errors_found",
        "total_errors": total,
        "total_formulas": formulas,
        "error_summary": summary,
    }


if __name__ == "__main__":
    print(json.dumps(run_recalc(XLSX), indent=2))

